"use client";

/**
 * The last error boundary: it catches what `app/error.tsx` cannot — an error thrown by the root layout itself.
 * It replaces the root layout, so it renders its own <html> and <body>, and it cannot rely on the app's providers,
 * fonts or theme: keep it plain and self-contained.
 *
 * Generated by `design-md-to-app`. The `errors` level of `module-add observability` adds
 * `Sentry.captureException(error)` in the effect below, so the error reaches the tracker with its release.
 */
import { useEffect } from "react";

export default function GlobalError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    // module-add observability (errors) replaces this line with Sentry.captureException(error).
    console.error("[global-error.tsx]", error);
  }, [error]);

  return (
    <html lang="en">
      <body style={{ fontFamily: "system-ui, sans-serif", display: "grid", placeItems: "center", minHeight: "100vh", margin: 0 }}>
        <main style={{ maxWidth: 420, textAlign: "center", padding: 24 }}>
          <h1 style={{ fontSize: 20, margin: "0 0 8px" }}>Something went wrong</h1>
          <p style={{ margin: "0 0 16px", opacity: 0.7 }}>
            The page could not load. Try again; if it keeps happening, quote this code to support:
            {error.digest ? <code> {error.digest}</code> : null}
          </p>
          <button type="button" onClick={() => reset()} style={{ padding: "8px 16px", cursor: "pointer" }}>
            Try again
          </button>
        </main>
      </body>
    </html>
  );
}
